    "raw",
    enc.encode(masterPassword),
    "PBKDF2",
    false,
    ["deriveKey"],
  );

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: salt,
      iterations: 100_000,
      hash: "SHA-256",
    },
    passwordKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  function makeSecretKey(owner: string, name: string): string {
    return SECRET_PREFIX + bytesToBase64(enc.encode(owner)) + "|" + bytesToBase64(enc.encode(name));
  }

  function makeOwnerPrefix(owner: string): string {
    return SECRET_PREFIX + bytesToBase64(enc.encode(owner)) + "|";
  }

  function makeAAD(owner: string, name: string): Uint8Array {
    const ownerBytes = enc.encode(owner);
    const nameBytes = enc.encode(name);
    const total = 8 + ownerBytes.length + nameBytes.length;
    const aad = new Uint8Array(total);
    const view = new DataView(aad.buffer);
    view.setUint32(0, ownerBytes.length, false);
    view.setUint32(4, nameBytes.length, false);
    aad.set(ownerBytes, 8);
    aad.set(nameBytes, 8 + ownerBytes.length);
    return aad;
  }

