    const iv = crypto.getRandomValues(new Uint8Array(12));
    const aad = makeAAD(owner, name);
    const plaintext = enc.encode(value);

    const ciphertext = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: aad },
      aesKey,
      plaintext,
    );

    // Prepend IV to ciphertext
    const combined = new Uint8Array(12 + ciphertext.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(ciphertext), 12);

    const key = makeSecretKey(owner, name);
    await storage.set(key, bytesToBase64(combined));
  }

  async function get(owner: string, name: string): Promise<string | undefined> {
    const key = makeSecretKey(owner, name);
    const stored = await storage.get(key);
    if (stored === undefined) return undefined;

    try {
      const combined = base64ToBytes(stored);
      if (combined.length < 28) {
        throw new Error("Tampered or invalid secret data");
      }
      const iv = combined.subarray(0, 12);
      const ciphertext = combined.subarray(12);
      const aad = makeAAD(owner, name);

      const plaintext = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv, additionalData: aad },
        aesKey,
        ciphertext,
      );

      return dec.decode(plaintext);
    } catch (e) {
      // Re-throw as a generic error to not leak details
      throw new Error("Failed to decrypt secret: possible tampering detected");
    }
